-- declare-capability-candidate-filing.sql
--
-- Phase 1 of the candidate write seam: declare the non-executable change kind
-- `capability-candidate` in the selected sda-kernel-boot-data-access.v1
-- authority. Admission validates the bundle envelope and its receipt reference
-- and returns ADMITTED or HELD with field-named findings; filing writes exactly
-- one AUTHORITY receipt under sidefx:candidates and no other row. The installer
-- (model.register_capability_candidate) never touches capability, contract,
-- scenario, port, transformation or provider rows; replay of byte-identical
-- bundle bytes is idempotent (already_installed) and a revised bundle is HELD
-- as CANDIDATE_REVISION_NOT_ADMITTED (a revision needs a new candidate id).
--
-- Also republished as change contracts (data only, no kind uses them yet):
-- capability-candidate-receipt.v1 and alignment-evaluation.v1.
--
-- The declared model/source guard inventory is explicitly empty in the selected
-- authority. No guard is dropped or recreated.
--
-- Idempotent: a second run finds the selected content digest already the new one
-- and re-declares nothing; the CREATE OR ALTER procedure is re-runnable.
--
-- Installed copy. The from-transaction preflight passed on the rollback copy first.
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @lock int;
EXEC @lock=sys.sp_getapplock @Resource=N'sidefx:model-write',@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=30000;
IF @lock<0 THROW 51000,N'CANDIDATE_FILING_LOCK_FAILED',1;
IF EXISTS(SELECT 1 FROM sys.triggers t JOIN sys.tables p ON p.object_id=t.parent_id JOIN sys.schemas s ON s.schema_id=p.schema_id
 WHERE s.name IN (N'model',N'source')) THROW 51000,N'GUARD_INVENTORY_CHANGED_REDECLARE_EXPLICIT_SET',1;
DECLARE @estate bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1);
DECLARE @authority_id nvarchar(400)=N'sda-kernel-boot-data-access.v1' COLLATE Latin1_General_100_BIN2;
DECLARE @prior_content nvarchar(80)=N'sha256:84c0ee351bc0332a56a30f0969658d5a526216485d3b8a3e2ee9d2e286fe72cb';
DECLARE @new_content nvarchar(80)=N'sha256:7c30b9f44eb6c9fe3c0a611c3f5d739cdd3ba00eeb6dd9385bbd1bf6a1eccf79';
DECLARE @selected nvarchar(80)=(SELECT JSON_VALUE(definition_json,'$.semantics.contentDigest') FROM analysis.v_selected_semantic_definition
 WHERE estate_model_pk=@estate AND object_kind='AUTHORITY' AND declared_id=@authority_id);
IF @selected IS NULL THROW 51000,N'KERNEL_BOOT_AUTHORITY_NOT_SELECTED',1;
IF @selected NOT IN (@prior_content,@new_content) THROW 51000,N'KERNEL_BOOT_AUTHORITY_CHANGED_REBASE_DECLARATION',1;
GO
CREATE OR ALTER PROCEDURE model.register_capability_candidate @document nvarchar(max)
WITH EXECUTE AS OWNER
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 IF @@TRANCOUNT<>1 OR XACT_STATE()<>1 THROW 51000,'CANDIDATE_FILING_TRANSACTION_REQUIRED',1;
 IF ISJSON(@document)<>1 OR JSON_VALUE(@document,'$.contractId')<>N'capability-candidate-bundle.v1'
  THROW 51000,'CANDIDATE_BUNDLE_DOCUMENT_REQUIRED',1;
 DECLARE @estate bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1);
 DECLARE @candidate nvarchar(400)=JSON_VALUE(@document,'$.candidateId');
 DECLARE @namespace nvarchar(400)=N'sidefx:candidates';
 DECLARE @receipt_id nvarchar(400)=@candidate+N'.receipt.v1';
 DECLARE @digest nvarchar(100)=N'sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(varchar(max),@document COLLATE Latin1_General_100_BIN2_UTF8))),2));
 DECLARE @prior nvarchar(max)=(SELECT JSON_QUERY(definition_json,'$.semantics.document')
  FROM analysis.v_selected_semantic_definition WHERE estate_model_pk=@estate
  AND object_kind='AUTHORITY' AND namespace_id=@namespace AND declared_id=@receipt_id);
 IF @prior IS NOT NULL
 BEGIN
  IF JSON_VALUE(@prior,'$.bundleDigest')<>@digest THROW 51000,'CANDIDATE_REVISION_NOT_ADMITTED',1;
  SELECT N'already_installed' AS result_set,@candidate AS candidate_id,@digest AS bundle_digest;
  RETURN;
 END;
 DECLARE @admissions nvarchar(max)=(
  SELECT j.[key] AS altitude,JSON_VALUE(j.value,'$.contractId') AS contractId,
   N'admit-capability-candidate' AS admissionId,N'ADMITTED' AS disposition,
   N'CAPABILITY_CANDIDATE_ALTITUDE_DECLARED' AS reason
  FROM OPENJSON(@document,'$.altitudes') j ORDER BY j.[key] COLLATE Latin1_General_100_BIN2 FOR JSON PATH);
 DECLARE @receipt nvarchar(max)=N'{"contractId":"capability-candidate-receipt.v1","candidateId":"'
  +STRING_ESCAPE(@candidate,N'json')+N'","bundleDigest":"'+@digest+N'","admissions":'+@admissions
  +N',"alignment":null,"install":{"disposition":"CANDIDATE","altitudeReceipts":[]}'
  +N',"review":{"decision":"PENDING","reviewerAuthorityId":null,"decidedAt":null}}';
 DECLARE @semantics nvarchar(max)=(SELECT JSON_QUERY(@receipt) AS document FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
 DECLARE @object bigint,@definition bigint,@definition_digest binary(32);
 EXEC model.put_semantic_definition 'AUTHORITY',@namespace,@receipt_id,@semantics,@object OUTPUT,@definition OUTPUT,@definition_digest OUTPUT;
 SELECT N'candidate_filed' AS result_set,@candidate AS candidate_id,@digest AS bundle_digest;
END;
GO
DECLARE @estate bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1);
DECLARE @authority_id nvarchar(400)=N'sda-kernel-boot-data-access.v1' COLLATE Latin1_General_100_BIN2;
DECLARE @prior_content nvarchar(80)=N'sha256:84c0ee351bc0332a56a30f0969658d5a526216485d3b8a3e2ee9d2e286fe72cb';
DECLARE @new_content nvarchar(80)=N'sha256:7c30b9f44eb6c9fe3c0a611c3f5d739cdd3ba00eeb6dd9385bbd1bf6a1eccf79';
DECLARE @selected nvarchar(80)=(SELECT JSON_VALUE(definition_json,'$.semantics.contentDigest') FROM analysis.v_selected_semantic_definition
 WHERE estate_model_pk=@estate AND object_kind='AUTHORITY' AND declared_id=@authority_id);
DECLARE @body nvarchar(max)=N'{"$schema":"https://schemas.scenario-driven.dev/kernel/sda-kernel-boot-data-access-authority.v1.schema.json","dataAccessType":"kernel-boot-data-access-authority.v1","authorityId":"sda-kernel-boot-data-access.v1","authorityVersion":"1.0.0","lifecycle":"ADMITTED","family":"Declared data-access reads for the kernel boot. Every read the boot needs is declared here as a stable read id, a source kind, the statement or document it reads, its bind parameters, and its recordset mapping, together with the session policy (the estate''s model-definition read and the reader identity) the pinned session resolves from this authority. The kernel resolves read ids and dispatches to the declared source realization; statement text is data, never resolver code.","runtimeResolution":{"authorityRef":"kernel/semantic-authority/consumer/sda-kernel-boot-data-access.authority.v1.json","resolutionKind":"declared-constant","resolverConstant":"DATA_ACCESS_AUTHORITY_REF","resolvedBy":"languages/typescript/src/kernel/bootstrap/data-access.mjs","base":"the kernel repository root, derived from the data-access module location, overridable by an explicit sdaRoot supplied by a caller"},"sourceKinds":[{"sourceKind":"tsql","meaning":"A declared statement batch executed through one pinned read session; recordsets pass through as the session returns them.","realization":"languages/typescript/src/kernel/bootstrap/data-access.mjs (built-in source resolver)","executorParameter":"query"}],"reads":[{"readId":"capability-authority","purpose":"Read the selected capability root row: identity, namespace, declared graph source, CLI configuration and (when requested) retained documents.","sourceKind":"tsql","statement":"-- Declared capability-authority read. Resolve a scenario''s reachable graph,\n-- including transitions and nested scenario invocations. Other registered\n-- scenarios remain available without becoming unreachable compiler cells.\nDECLARE @graphs TABLE(row_id int IDENTITY,capability_id nvarchar(400),scenario_id nvarchar(400),namespace_id nvarchar(400),\n graph_source nvarchar(max),cli_configuration nvarchar(max),documents nvarchar(max));\nINSERT @graphs(capability_id,scenario_id,namespace_id,graph_source,cli_configuration,documents)\n SELECT g.capability_id,COALESCE(JSON_VALUE(@input,''$.scenarioId''),g.root_scenario_id),g.namespace_id,g.graph_source,g.cli_configuration,g.documents\n FROM analysis.capability_graph_source(CONVERT(nvarchar(400),JSON_VALUE(@input,''$.capabilityId'')),\n  CONVERT(bit,JSON_VALUE(@input,''$.includeDocuments'')),CONVERT(nvarchar(400),JSON_VALUE(@input,''$.namespaceId''))) g\n WHERE g.estate_model_pk=@estate_model_pk AND (JSON_VALUE(@input,''$.namespaceId'') IS NULL OR g.namespace_id=JSON_VALUE(@input,''$.namespaceId''))\n AND (JSON_VALUE(@input,''$.scenarioId'') IS NULL OR EXISTS(SELECT 1 FROM OPENJSON(g.graph_source,''$.scenarios'')\n  WHERE JSON_VALUE(value,''$.scenarioId'')=JSON_VALUE(@input,''$.scenarioId'')));\nDECLARE @edges TABLE(row_id int,source_id nvarchar(400) COLLATE Latin1_General_100_BIN2,target_id nvarchar(400) COLLATE Latin1_General_100_BIN2);\nINSERT @edges\n SELECT g.row_id,JSON_VALUE(t.value,''$.from.scenarioId''),JSON_VALUE(t.value,''$.to.scenarioId'') FROM @graphs g CROSS APPLY OPENJSON(g.graph_source,''$.transitions'') t\n UNION\n SELECT g.row_id,JSON_VALUE(a.value,''$.owningScenarioId''),JSON_VALUE(o.value,''$.scenarioId'')\n FROM @graphs g CROSS APPLY OPENJSON(g.graph_source,''$.executionAuthorities'') a CROSS APPLY OPENJSON(a.value,''$.operations'') o\n WHERE JSON_VALUE(o.value,''$.kind'')=''invoke-scenario'';\nDECLARE @reachable TABLE(row_id int,scenario_id nvarchar(400) COLLATE Latin1_General_100_BIN2,PRIMARY KEY(row_id,scenario_id));\nINSERT @reachable SELECT row_id,scenario_id FROM @graphs;\nWHILE 1=1\nBEGIN\n INSERT @reachable SELECT DISTINCT e.row_id,e.target_id FROM @edges e JOIN @reachable r ON r.row_id=e.row_id AND r.scenario_id=e.source_id\n WHERE e.target_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM @reachable found WHERE found.row_id=e.row_id AND found.scenario_id=e.target_id);\n IF @@ROWCOUNT=0 BREAK;\nEND;\nUPDATE g SET graph_source=JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(g.graph_source,''$.rootScenarioId'',g.scenario_id),\n ''$.scenarios'',JSON_QUERY(COALESCE((SELECT N''[''+STRING_AGG(CONVERT(nvarchar(max),s.value),N'','') WITHIN GROUP(ORDER BY CONVERT(int,s.[key]))+N'']''\n  FROM OPENJSON(g.graph_source,''$.scenarios'') s JOIN @reachable r ON r.row_id=g.row_id AND r.scenario_id=JSON_VALUE(s.value,''$.scenarioId'')),N''[]''))),\n ''$.executionAuthorities'',JSON_QUERY(COALESCE((SELECT N''[''+STRING_AGG(CONVERT(nvarchar(max),a.value),N'','') WITHIN GROUP(ORDER BY CONVERT(int,a.[key]))+N'']''\n  FROM OPENJSON(g.graph_source,''$.executionAuthorities'') a JOIN @reachable r ON r.row_id=g.row_id AND r.scenario_id=JSON_VALUE(a.value,''$.owningScenarioId'')),N''[]''))),\n ''$.transitions'',JSON_QUERY(COALESCE((SELECT N''[''+STRING_AGG(CONVERT(nvarchar(max),t.value),N'','') WITHIN GROUP(ORDER BY CONVERT(int,t.[key]))+N'']''\n  FROM OPENJSON(g.graph_source,''$.transitions'') t JOIN @reachable r ON r.row_id=g.row_id AND r.scenario_id=JSON_VALUE(t.value,''$.from.scenarioId'')),N''[]'')))\nFROM @graphs g;\nSELECT capability_id,scenario_id,namespace_id,graph_source,cli_configuration,documents FROM @graphs ORDER BY row_id;\n","parameters":[{"parameter":"input","kind":"invocation-input-json","fields":["capabilityId","includeDocuments","namespaceId"]},{"parameter":"estate_model_pk","kind":"pinned-session"}],"resultMapping":{"recordsets":[{"index":0,"role":"capability-root","columns":["capability_id","scenario_id","namespace_id","graph_source","cli_configuration","documents"]}]}},{"readId":"capability-closure","purpose":"Resolve the selected scenario version of the selected capability and read its declared downstream invocation closure.","sourceKind":"tsql","statement":"\nDECLARE @capability_id nvarchar(4000)=JSON_VALUE(@input,''$.capabilityId''),\n        @scenario_id nvarchar(4000)=JSON_VALUE(@input,''$.scenarioId''),\n        @namespace_id nvarchar(4000)=JSON_VALUE(@input,''$.namespaceId'');\nDECLARE @matches bigint,@capability_version_pk bigint,@scenario_version_pk bigint;\nSELECT @matches=COUNT_BIG(*),@capability_version_pk=MAX(ec.capability_version_pk)\nFROM model.estate_capability ec\nJOIN model.capability c ON c.capability_pk=ec.capability_pk\nJOIN model.identity_namespace n ON n.namespace_pk=c.namespace_pk\nWHERE ec.estate_model_pk=@estate_model_pk AND c.capability_id=@capability_id\n  AND (@namespace_id IS NULL OR n.namespace_id=@namespace_id);\nIF @matches=0 THROW 51000,''CAPABILITY_NOT_FOUND'',1;\nIF @matches<>1 THROW 51000,''CAPABILITY_NAMESPACE_AMBIGUOUS'',1;\nSELECT @matches=COUNT_BIG(*),@scenario_version_pk=MAX(cs.scenario_version_pk)\nFROM model.capability_scenario cs JOIN model.scenario s ON s.scenario_pk=cs.scenario_pk\nWHERE cs.capability_version_pk=@capability_version_pk AND s.scenario_id=@scenario_id;\nIF @matches=0 THROW 51000,''SCENARIO_NOT_IN_CAPABILITY'',1;\nIF @matches<>1 THROW 51000,''SCENARIO_NAMESPACE_AMBIGUOUS'',1;\nSELECT DISTINCT s.scenario_id AS downstream_scenario_id,cl.minimum_depth,cl.cycle_detected,\n       sc.capability_id AS owning_capability_id,\n       i.input_id,e.event_id,e.responsibility,o.outcome_id,sv.definition_digest AS scenario_definition_digest\nFROM analysis.v_scenario_invocation_closure cl\nJOIN model.scenario_version sv ON sv.scenario_version_pk=cl.downstream_scenario_version_pk\nJOIN model.scenario s ON s.scenario_pk=sv.scenario_pk\nJOIN model.capability sc ON sc.capability_pk=s.capability_pk\nLEFT JOIN model.scenario_input i ON i.scenario_version_pk=sv.scenario_version_pk\nLEFT JOIN model.scenario_event e ON e.scenario_version_pk=sv.scenario_version_pk\nLEFT JOIN model.scenario_outcome o ON o.scenario_version_pk=sv.scenario_version_pk\nWHERE cl.capability_version_pk=@capability_version_pk AND cl.selected_scenario_version_pk=@scenario_version_pk\nORDER BY cl.minimum_depth,s.scenario_id\nOPTION(MAXRECURSION 32767);","parameters":[{"parameter":"input","kind":"invocation-input-json","fields":["capabilityId","scenarioId","namespaceId"]},{"parameter":"estate_model_pk","kind":"pinned-session"}],"resultMapping":{"recordsets":[{"index":0,"role":"invocation-closure","columns":["downstream_scenario_id","minimum_depth","cycle_detected","owning_capability_id","input_id","event_id","responsibility","outcome_id","scenario_definition_digest"]}]}},{"readId":"scenario-resolver-map","purpose":"Read the language-resolution map and per-target readiness for the selected capability/scenario, plus the same invocation closure.","sourceKind":"tsql","statement":"\nDECLARE @capability_id nvarchar(4000)=JSON_VALUE(@input,''$.capabilityId''),\n        @scenario_id nvarchar(4000)=JSON_VALUE(@input,''$.scenarioId''),\n        @namespace_id nvarchar(4000)=JSON_VALUE(@input,''$.namespaceId''),\n        @target nvarchar(4000)=JSON_VALUE(@input,''$.target'');\nDECLARE @matches bigint,@capability_version_pk bigint,@scenario_version_pk bigint;\nSELECT @matches=COUNT_BIG(*),@capability_version_pk=MAX(ec.capability_version_pk)\nFROM model.estate_capability ec\nJOIN model.capability c ON c.capability_pk=ec.capability_pk\nJOIN model.identity_namespace n ON n.namespace_pk=c.namespace_pk\nWHERE ec.estate_model_pk=@estate_model_pk AND c.capability_id=@capability_id\n  AND (@namespace_id IS NULL OR n.namespace_id=@namespace_id);\nIF @matches=0 THROW 51000,''CAPABILITY_NOT_FOUND'',1;\nIF @matches<>1 THROW 51000,''CAPABILITY_NAMESPACE_AMBIGUOUS'',1;\nSELECT @matches=COUNT_BIG(*),@scenario_version_pk=MAX(cs.scenario_version_pk)\nFROM model.capability_scenario cs JOIN model.scenario s ON s.scenario_pk=cs.scenario_pk\nWHERE cs.capability_version_pk=@capability_version_pk AND s.scenario_id=@scenario_id;\nIF @matches=0 THROW 51000,''SCENARIO_NOT_IN_CAPABILITY'',1;\nIF @matches<>1 THROW 51000,''SCENARIO_NAMESPACE_AMBIGUOUS'',1;\nIF @target IS NOT NULL AND NOT EXISTS (\n    SELECT 1 FROM analysis.v_declared_platform_implementation\n    WHERE estate_model_pk=@estate_model_pk AND target_language=@target\n) THROW 51000,''TARGET_NOT_DECLARED'',1;\nSET ROWCOUNT 0;\nSELECT * INTO #resolver_map\nFROM analysis.v_scenario_language_resolution\nWHERE estate_model_pk=@estate_model_pk AND capability_version_pk=@capability_version_pk\n  AND selected_scenario_version_pk=@scenario_version_pk\n  AND (@target IS NULL OR target_language=@target)\nOPTION(RECOMPILE,MAXRECURSION 32767);\nSELECT capability_id,scenario_id,downstream_scenario_id,altitude,requirement_kind,\n       requirement_id,requirement_use,target_language,provenance_class,\n       source_definition_pk,source_pointer,requirement_definition_pk,requirement_definition_digest,\n       resolver_id,provider_id,provider_definition_pk,provider_profile_id,profile_definition_pk,\n       implementation_id,implementation_export,resolution_candidate_count,\n       mechanic_source_digest,registry_source_digest,declared_authority_digest,\n       resolution_status,diagnostic,repair_boundary,implementation_evidence_state,conformance_status\nFROM #resolver_map\nORDER BY target_language,minimum_depth,downstream_scenario_id,requirement_use,implementation_id;\nWITH obligations AS (\n    SELECT target_language,downstream_scenario_version_pk,requirement_use,\n           MAX(CASE WHEN resolution_status<>''RESOLVED'' THEN 1 ELSE 0 END) AS is_open\n    FROM #resolver_map GROUP BY target_language,downstream_scenario_version_pk,requirement_use\n)\nSELECT @capability_id AS capability_id,@scenario_id AS scenario_id,target_language,\n       COUNT_BIG(*) AS requirement_count,SUM(CONVERT(bigint,is_open)) AS open_requirement_count,\n       CASE WHEN SUM(is_open)=0 THEN ''CAN_ATTEMPT_EMBODIMENT'' ELSE ''NOT_OBSERVABLE'' END AS readiness,\n       ''NOT_EVALUATED'' AS conformance_status\nFROM obligations GROUP BY target_language ORDER BY target_language;\nSELECT DISTINCT s.scenario_id AS downstream_scenario_id,cl.minimum_depth,cl.cycle_detected,\n       i.input_id,e.event_id,e.responsibility,o.outcome_id,sv.definition_digest AS scenario_definition_digest\nFROM analysis.v_scenario_invocation_closure cl\nJOIN model.scenario_version sv ON sv.scenario_version_pk=cl.downstream_scenario_version_pk\nJOIN model.scenario s ON s.scenario_pk=sv.scenario_pk\nJOIN model.capability sc ON sc.capability_pk=s.capability_pk\nLEFT JOIN model.scenario_input i ON i.scenario_version_pk=sv.scenario_version_pk\nLEFT JOIN model.scenario_event e ON e.scenario_version_pk=sv.scenario_version_pk\nLEFT JOIN model.scenario_outcome o ON o.scenario_version_pk=sv.scenario_version_pk\nWHERE cl.capability_version_pk=@capability_version_pk AND cl.selected_scenario_version_pk=@scenario_version_pk\nORDER BY cl.minimum_depth,s.scenario_id\nOPTION(MAXRECURSION 32767);","parameters":[{"parameter":"input","kind":"invocation-input-json","fields":["capabilityId","scenarioId","namespaceId","target"]},{"parameter":"estate_model_pk","kind":"pinned-session"}],"resultMapping":{"recordsets":[{"index":0,"role":"resolver-map","columns":["capability_id","scenario_id","downstream_scenario_id","altitude","requirement_kind","requirement_id","requirement_use","target_language","provenance_class","source_definition_pk","source_pointer","requirement_definition_pk","requirement_definition_digest","resolver_id","provider_id","provider_definition_pk","provider_profile_id","profile_definition_pk","implementation_id","implementation_export","resolution_candidate_count","mechanic_source_digest","registry_source_digest","declared_authority_digest","resolution_status","diagnostic","repair_boundary","implementation_evidence_state","conformance_status"]},{"index":1,"role":"target-readiness","columns":["capability_id","scenario_id","target_language","requirement_count","open_requirement_count","readiness","conformance_status"]},{"index":2,"role":"invocation-closure","columns":["downstream_scenario_id","minimum_depth","cycle_detected","input_id","event_id","responsibility","outcome_id","scenario_definition_digest"]}]}},{"readId":"mechanic-definitions","purpose":"Read the selected model mechanic definitions as JSON rows.","sourceKind":"tsql","statement":"SELECT definition_json FROM analysis.v_selected_semantic_definition\nWHERE estate_model_pk=@estate_model_pk AND object_kind=''MECHANIC''","parameters":[{"parameter":"estate_model_pk","kind":"pinned-session"}],"resultMapping":{"recordsets":[{"index":0,"role":"mechanic-definitions","columns":["definition_json"]}]}},{"readId":"execution-delivery","purpose":"Read the declared execution-delivery provider configuration and the declared default target of the read-capability-authority port.","sourceKind":"tsql","statement":"SELECT declared_id AS provider_id,\n    JSON_QUERY(definition_json,''$.semantics.executionDelivery'') AS configuration\n    FROM analysis.v_selected_semantic_definition\n    WHERE estate_model_pk=@estate_model_pk AND object_kind=''PROVIDER''\n      AND JSON_QUERY(definition_json,''$.semantics.executionDelivery'') IS NOT NULL;\n    SELECT JSON_VALUE(definition_json,''$.semantics.configuration.defaultTarget'') AS default_target\n    FROM analysis.v_selected_semantic_definition\n    WHERE estate_model_pk=@estate_model_pk AND object_kind=''PORT''\n      AND namespace_id=''sidefx:capability:read-capability-authority''\n      AND declared_id=''read-capability-authority-port'';","parameters":[{"parameter":"estate_model_pk","kind":"pinned-session"}],"resultMapping":{"recordsets":[{"index":0,"role":"execution-delivery-providers","columns":["provider_id","configuration"]},{"index":1,"role":"execution-delivery-target","columns":["default_target"]}]}},{"readId":"provider-authority","purpose":"Resolve one declared provider authority by its stable identity or by a locator (source path or published relative reference), returning the exact retained content bytes and their digest. Providers verify the bound digest over these bytes, so no repository path is dereferenced at runtime.","sourceKind":"tsql","statement":"DECLARE @authority_id nvarchar(400)=CONVERT(nvarchar(400), JSON_VALUE(@input,''$.authorityId''));\nDECLARE @reference nvarchar(400)=CONVERT(nvarchar(400), JSON_VALUE(@input,''$.reference''));\nIF @authority_id IS NULL AND @reference IS NULL THROW 51000,''PROVIDER_AUTHORITY_REFERENCE_REQUIRED'',1;\nSELECT d.declared_id,\n       JSON_VALUE(d.definition_json,''$.semantics.authorityId'') AS authority_id,\n       JSON_VALUE(d.definition_json,''$.semantics.platformCapabilityId'') AS platform_capability_id,\n       JSON_VALUE(d.definition_json,''$.semantics.contentDigest'') AS content_digest,\n       co.byte_length,\n       co.content_bytes\nINTO #declared_provider_authority\nFROM analysis.v_selected_semantic_definition d\nJOIN source.content_object co\n  ON co.content_digest=CONVERT(binary(32),REPLACE(JSON_VALUE(d.definition_json,''$.semantics.contentDigest''),''sha256:'',''''),2)\nWHERE d.estate_model_pk=@estate_model_pk AND d.object_kind=''AUTHORITY''\n  AND (@authority_id IS NULL OR d.declared_id=@authority_id)\n  AND (@reference IS NULL OR d.declared_id=@reference\n       OR JSON_VALUE(d.definition_json,''$.semantics.sourcePath'')=@reference\n       OR EXISTS (SELECT 1 FROM OPENJSON(d.definition_json,''$.semantics.locators'') l WHERE l.value=@reference));\nDECLARE @matches bigint=(SELECT COUNT_BIG(*) FROM #declared_provider_authority);\nIF @matches=0 THROW 51000,''PROVIDER_AUTHORITY_NOT_DECLARED'',1;\nIF @matches>1 THROW 51000,''PROVIDER_AUTHORITY_AMBIGUOUS'',1;\nSELECT * FROM #declared_provider_authority;","parameters":[{"parameter":"input","kind":"invocation-input-json","fields":["authorityId","reference","digest"]},{"parameter":"estate_model_pk","kind":"pinned-session"}],"resultMapping":{"recordsets":[{"index":0,"role":"declared-provider-authority","columns":["declared_id","authority_id","platform_capability_id","content_digest","byte_length","content_bytes"]}]}},{"readId":"admit-provider-binding-change","classification":"observation","sourceKind":"tsql","statement":"DECLARE @wrapped nvarchar(max)=(SELECT JSON_VALUE(@input,''$.providerId'') AS providerId,JSON_QUERY(@input) AS input FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);\nDECLARE @authored TABLE(document nvarchar(max));\nINSERT @authored EXEC sys.sp_executesql N''DECLARE @estate bigint=@estate_model_pk;\nDECLARE @provider_id nvarchar(400)=NULLIF(JSON_VALUE(@input,''''$.providerId''''),N'''''''');\nDECLARE @change nvarchar(max)=JSON_QUERY(@input,''''$.input'''');\nDECLARE @findings TABLE (ordinal int IDENTITY(1,1), code nvarchar(100), field nvarchar(400), message nvarchar(2000));\nIF @provider_id IS NULL OR @change IS NULL OR ISJSON(@change)<>1\n INSERT @findings(code,field,message) VALUES(N''''CHANGE_DOCUMENT_REQUIRED'''',NULL,N''''supply providerId and a JSON change document as --input'''');\nELSE BEGIN\n IF NOT EXISTS (SELECT 1 FROM analysis.v_selected_semantic_definition d\n   WHERE d.estate_model_pk=@estate AND d.object_kind=''''PROVIDER'''' AND d.declared_id=@provider_id)\n  INSERT @findings(code,field,message) VALUES(N''''PROVIDER_NOT_DECLARED'''',NULL,N''''no provider declaration matches ''''+@provider_id);\n DECLARE @lower nvarchar(max)=LOWER(@change);\n IF CHARINDEX(N''''\"password\"'''',@lower)>0 OR CHARINDEX(N''''\"secret\"'''',@lower)>0 OR CHARINDEX(N''''\"apikey\"'''',@lower)>0\n  OR CHARINDEX(N''''\"api_key\"'''',@lower)>0 OR CHARINDEX(N''''\"token\"'''',@lower)>0\n  OR CHARINDEX(N''''\"credentialvalue\"'''',@lower)>0 OR CHARINDEX(N''''\"privatekey\"'''',@lower)>0\n   INSERT @findings(code,field,message) VALUES(N''''SECRET_MATERIAL_REJECTED'''',NULL,N''''the change document carries secret material; environment secrets are never accepted here'''');\n DECLARE @host nvarchar(400)=NULLIF(JSON_VALUE(@change,''''$.endpoint.host''''),N'''''''');\n DECLARE @method nvarchar(20)=NULLIF(JSON_VALUE(@change,''''$.endpoint.method''''),N'''''''');\n DECLARE @path_prefix nvarchar(1000)=NULLIF(JSON_VALUE(@change,''''$.endpoint.pathPrefix''''),N'''''''');\n DECLARE @binding_id nvarchar(400)=NULLIF(JSON_VALUE(@change,''''$.bindingId''''),N'''''''');\n DECLARE @rule_id nvarchar(400)=NULLIF(JSON_VALUE(@change,''''$.credential.injectionRuleId''''),N'''''''');\n DECLARE @reference_name nvarchar(400)=NULLIF(JSON_VALUE(@change,''''$.credential.referenceName''''),N'''''''');\n DECLARE @effect_scope nvarchar(400)=NULLIF(JSON_VALUE(@change,''''$.effectScope''''),N'''''''');\n IF @host IS NULL INSERT @findings(code,field,message) VALUES(N''''ENDPOINT_FIELD_REQUIRED'''',N''''endpoint.host'''',N''''a change must declare the host it reaches'''');\n IF @method IS NULL INSERT @findings(code,field,message) VALUES(N''''ENDPOINT_FIELD_REQUIRED'''',N''''endpoint.method'''',N''''a change must declare the HTTP method'''');\n IF @path_prefix IS NULL INSERT @findings(code,field,message) VALUES(N''''ENDPOINT_FIELD_REQUIRED'''',N''''endpoint.pathPrefix'''',N''''a change must declare the admitted path prefix'''');\n IF @binding_id IS NULL INSERT @findings(code,field,message) VALUES(N''''ENDPOINT_FIELD_REQUIRED'''',N''''bindingId'''',N''''a change must declare the canonical binding identity'''');\n IF @rule_id IS NULL INSERT @findings(code,field,message) VALUES(N''''CREDENTIAL_FIELD_REQUIRED'''',N''''credential.injectionRuleId'''',N''''a change must name the declared injection rule'''');\n IF @reference_name IS NULL INSERT @findings(code,field,message) VALUES(N''''CREDENTIAL_FIELD_REQUIRED'''',N''''credential.referenceName'''',N''''a change must name the declared credential reference''''); IF @effect_scope IS NULL INSERT @findings(code,field,message) VALUES(N''''ENDPOINT_FIELD_REQUIRED'''',N''''effectScope'''',N''''a change must declare its effect scope'''');\n DECLARE @outcome_contract nvarchar(400)=NULLIF(JSON_VALUE(@change,''''$.outcomeContractId''''),N'''''''');\n DECLARE @schema nvarchar(max)=NULL;\n IF @outcome_contract IS NOT NULL\n  SELECT TOP 1 @schema=CONVERT(nvarchar(max),CONVERT(varchar(max),co.content_bytes) COLLATE Latin1_General_100_BIN2_UTF8)\n  FROM analysis.v_selected_semantic_definition d\n  JOIN source.content_object co ON co.content_digest=CONVERT(binary(32),REPLACE(JSON_VALUE(d.definition_json,''''$.semantics.schema_digest''''),''''sha256:'''',''''''''),2)\n  WHERE d.estate_model_pk=@estate AND d.object_kind=''''CONTRACT'''' AND d.declared_id=@outcome_contract\n  ORDER BY d.semantic_object_definition_pk DESC;\n IF @schema IS NULL\n  INSERT @findings(code,field,message) VALUES(N''''OUTCOME_CONTRACT_SCHEMA_UNRESOLVED'''',N''''outcomeContractId'''',N''''no declared schema resolves for ''''+ISNULL(@outcome_contract,N''''(missing outcomeContractId)''''));\n ELSE BEGIN\n  DECLARE @mapping nvarchar(max)=JSON_QUERY(@change,''''$.mapping'''');\n  DECLARE @sample nvarchar(max)=JSON_QUERY(@change,''''$.observedSample'''');\n  DECLARE @required TABLE (field nvarchar(400) COLLATE Latin1_General_100_BIN2, expected_type nvarchar(40));\n  INSERT @required\n  SELECT j.[key],JSON_VALUE(j.value,''''$.type'''')\n  FROM OPENJSON(@schema,''''$.properties.payload.properties'''') j\n  WHERE j.[key] IN (SELECT value FROM OPENJSON(@schema,''''$.properties.payload.required''''));\n  DECLARE @field nvarchar(400),@expected nvarchar(40),@native nvarchar(1000),@value nvarchar(max);\n  DECLARE required_cursor CURSOR LOCAL FAST_FORWARD FOR SELECT field,expected_type FROM @required ORDER BY field;\n  OPEN required_cursor;\n  FETCH NEXT FROM required_cursor INTO @field,@expected;\n  WHILE @@FETCH_STATUS=0 BEGIN\n    SET @native=NULLIF(JSON_VALUE(@mapping,N''''$.\"''''+@field+''''\"''''),N'''''''');\n    IF @native IS NULL\n      INSERT @findings(code,field,message) VALUES(N''''CANONICAL_MAPPING_ABSENT'''',@field,N''''the mapping declares no native source for this canonical field'''');\n    ELSE IF @sample IS NOT NULL AND @native NOT LIKE N''''request:%'''' BEGIN\n      SET @value=JSON_VALUE(@sample,N''''$.''''+REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(@native,N''''.0.'''',N''''[0].''''),N''''.1.'''',N''''[1].''''),N''''.2.'''',N''''[2].''''),N''''.3.'''',N''''[3].''''),N''''.4.'''',N''''[4].''''),N''''.5.'''',N''''[5].''''),N''''.6.'''',N''''[6].''''),N''''.7.'''',N''''[7].''''),N''''.8.'''',N''''[8].''''),N''''.9.'''',N''''[9].''''));\n      IF @value IS NULL\n        INSERT @findings(code,field,message) VALUES(N''''NATIVE_PATH_NOT_OBSERVED'''',@field,N''''the observed sample carries no value at ''''+@native);\n      ELSE IF @expected=N''''string'''' AND TRY_CONVERT(decimal(38,10),@value) IS NOT NULL\n        INSERT @findings(code,field,message) VALUES(N''''NATIVE_TYPE_MISMATCH'''',@field,N''''canonical string expected at ''''+@native+N'''' but a number was observed'''');\n      ELSE IF @expected=N''''number'''' AND TRY_CONVERT(decimal(38,10),@value) IS NULL\n        INSERT @findings(code,field,message) VALUES(N''''NATIVE_TYPE_MISMATCH'''',@field,N''''canonical number expected at ''''+@native+N'''' but a non-number was observed'''');\n      ELSE IF @expected=N''''integer'''' AND TRY_CONVERT(bigint,@value) IS NULL        INSERT @findings(code,field,message) VALUES(N''''NATIVE_TYPE_MISMATCH'''',@field,N''''canonical integer expected at ''''+@native+N'''' but a non-integer was observed'''');\n    END\n    FETCH NEXT FROM required_cursor INTO @field,@expected;\n  END\n  CLOSE required_cursor; DEALLOCATE required_cursor;\n END\n DECLARE @record nvarchar(max)=NULL,@digest nvarchar(100)=NULL;\n IF @host IS NOT NULL AND @method IS NOT NULL AND @path_prefix IS NOT NULL AND @binding_id IS NOT NULL AND @rule_id IS NOT NULL AND @effect_scope IS NOT NULL\n BEGIN\n  SET @record=N''''{\"host\":\"''''+STRING_ESCAPE(@host,N''''json'''')+N''''\",\"method\":\"''''+STRING_ESCAPE(@method,N''''json'''')\n   +N''''\",\"pathPrefix\":\"''''+STRING_ESCAPE(@path_prefix,N''''json'''')+N''''\",\"providerId\":\"''''+STRING_ESCAPE(@provider_id,N''''json'''')\n   +N''''\",\"bindingId\":\"''''+STRING_ESCAPE(@binding_id,N''''json'''')+N''''\",\"credentialInjectionRuleId\":\"''''+STRING_ESCAPE(@rule_id,N''''json'''')\n   +N''''\",\"effectScope\":\"''''+STRING_ESCAPE(@effect_scope,N''''json'''')+N''''\"}'''';\n  SET @digest=N''''sha256:''''+LOWER(CONVERT(varchar(64),HASHBYTES(''''SHA2_256'''',CONVERT(varbinary(max),CONVERT(varchar(max),@record COLLATE Latin1_General_100_BIN2_UTF8))),2));\n END\nEND\nDECLARE @findings_json nvarchar(max)=ISNULL((SELECT code,field,message FROM @findings ORDER BY ordinal FOR JSON PATH),N''''[]'''');\nDECLARE @authored bit=CONVERT(bit,CASE WHEN (SELECT COUNT(*) FROM @findings)=0 THEN 1 ELSE 0 END);\nDECLARE @output nvarchar(max);\nSET @output=(\n SELECT N''''provider-binding-change-result.v1'''' AS contractId,N''''provider-binding-change.v1'''' AS documentType,\n   CASE WHEN @authored=1 THEN N''''PROVIDER_CHANGE_AUTHORED'''' ELSE N''''PROVIDER_CHANGE_HELD'''' END AS disposition,\n   @provider_id AS providerId,\n   CASE WHEN @authored=1 THEN JSON_QUERY(@change) ELSE NULL END AS change,\n   CASE WHEN @record IS NULL THEN NULL ELSE JSON_QUERY(@record) END AS canonicalEndpointRecord,\n   @digest AS endpointAuthorityDigest,\n   JSON_QUERY(@findings_json) AS findings,\n   CASE WHEN @authored=1 THEN JSON_QUERY(N''''{\"author\":\"author the declared change as one sql/migrations migration\",\"dryRun\":\"node ../scenario-driven-architecture/languages/typescript/src/kernel/bootstrap/run-migration.mjs <migration.sql>\",\"preflight\":\"node ../scenario-driven-architecture/languages/typescript/src/kernel/bootstrap/invoke-from-transaction.mjs <migration.sql> <capabilityId> <input.json>\",\"install\":\"replace the final rollback with a commit and run the lifecycle runner\" }'''') ELSE NULL END AS lifecycle\n FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);\nSELECT @output AS document;\n'',N''@estate_model_pk bigint,@input nvarchar(max)'',@estate_model_pk,@wrapped;\nSELECT CASE WHEN (SELECT COUNT(*) FROM @authored)=1 AND JSON_VALUE(document,''$.disposition'')=N''PROVIDER_CHANGE_AUTHORED'' THEN N''ADMITTED'' ELSE N''HELD'' END AS disposition,\n COALESCE(JSON_QUERY(document,''$.findings''),N''[]'') AS reason FROM @authored;"},{"readId":"admit-scenario-registration-change","classification":"observation","sourceKind":"tsql","statement":"DECLARE @capability nvarchar(400)=JSON_VALUE(@input,''$.capabilityId''),@id nvarchar(400)=JSON_VALUE(@input,''$.scenario.scenarioId'');\nDECLARE @namespace nvarchar(400)=N''sidefx:capability:''+@capability;\nDECLARE @reason nvarchar(400)=N''SCENARIO_REGISTRATION_ADMITTED'';\nDECLARE @prior nvarchar(max)=(SELECT JSON_QUERY(definition_json,''$.semantics.document'') FROM analysis.v_selected_semantic_definition\n WHERE estate_model_pk=@estate_model_pk AND object_kind=''AUTHORITY'' AND namespace_id=@namespace AND declared_id=@id+N''.change.v1'');\nIF NOT EXISTS(SELECT 1 FROM model.estate_capability ec JOIN model.capability c ON c.capability_pk=ec.capability_pk\n JOIN model.identity_namespace n ON n.namespace_pk=c.namespace_pk WHERE ec.estate_model_pk=@estate_model_pk AND c.capability_id=@capability AND n.namespace_id=N''sidefx:capabilities'')\n SET @reason=N''CAPABILITY_NOT_SELECTED'';\nIF (SELECT COUNT(*) FROM analysis.v_selected_semantic_definition WHERE estate_model_pk=@estate_model_pk AND object_kind=''CONTRACT''\n AND namespace_id=N''sidefx:contracts'' AND declared_id IN (JSON_VALUE(@input,''$.scenario.inputContract''),JSON_VALUE(@input,''$.scenario.outcomeContract'')))<>2\n SET @reason=N''SCENARIO_CONTRACT_NOT_SELECTED'';\nIF NOT EXISTS(SELECT 1 FROM analysis.v_selected_semantic_definition WHERE estate_model_pk=@estate_model_pk AND object_kind=''PORT''\n AND namespace_id=@namespace AND declared_id=JSON_VALUE(@input,''$.portBindings[0].portId'') AND definition_digest=0xa8e6acfe23df0f50fa857fc191c0bcca63a8ee953089e6825eb5beb92d92e63d)\n SET @reason=N''ADMITTED_PORT_CHANGED'';\nIF JSON_VALUE(@input,''$.scenario.eventAuthority'')<>@id+N''.v1'' OR JSON_VALUE(@input,''$.scenario.eventId'')<>@id+N''-requested''\n OR JSON_VALUE(@input,''$.operations[0].operationId'')<>@id+N''.operation.1''\n OR JSON_VALUE(@input,''$.operations[0].portId'')<>JSON_VALUE(@input,''$.portBindings[0].portId'')\n SET @reason=N''SCENARIO_REFERENCES_OUTSIDE_GRANT'';\nIF EXISTS(SELECT 1 FROM OPENJSON(@input,''$.fixtures'') WHERE LEFT(JSON_VALUE(value,''$.fixtureId''),LEN(@id)+1)<>@id+N''-'')\n SET @reason=N''FIXTURE_ID_OUTSIDE_GRANT'';\nIF @prior IS NOT NULL AND @prior COLLATE Latin1_General_100_BIN2<>@input COLLATE Latin1_General_100_BIN2\n SET @reason=N''SCENARIO_REVISION_NOT_ADMITTED'';\nIF @prior IS NULL AND (EXISTS(SELECT 1 FROM model.semantic_object so JOIN model.identity_namespace n ON n.namespace_pk=so.namespace_pk WHERE n.namespace_id=@namespace\n AND ((so.object_kind=''SCENARIO'' AND so.declared_id=@id) OR (so.object_kind=''EXECUTION_AUTHORITY'' AND so.declared_id=JSON_VALUE(@input,''$.scenario.eventAuthority''))\n OR (so.object_kind=''AUTHORITY'' AND so.declared_id=@id+N''.change.v1'')\n OR (so.object_kind=''FIXTURE'' AND so.declared_id IN (SELECT JSON_VALUE(value,''$.fixtureId'') FROM OPENJSON(@input,''$.fixtures'')))))\n OR EXISTS(SELECT 1 FROM model.scenario s JOIN model.capability c ON c.capability_pk=s.capability_pk\n JOIN model.identity_namespace n ON n.namespace_pk=c.namespace_pk WHERE c.capability_id=@capability AND n.namespace_id=N''sidefx:capabilities'' AND s.scenario_id=@id))\n SET @reason=N''SCENARIO_IDENTITY_ALREADY_OWNED'';\nSELECT CASE WHEN @reason=N''SCENARIO_REGISTRATION_ADMITTED'' THEN N''ADMITTED'' ELSE N''HELD'' END AS disposition,@reason AS reason;"},{"readId":"admit-capability-candidate","purpose":"Validate a model-authored capability candidate bundle envelope and its receipt reference; returns ADMITTED or HELD with field-named findings. Writes nothing.","classification":"observation","sourceKind":"tsql","statement":"DECLARE @findings TABLE(ordinal int IDENTITY(1,1),code nvarchar(100),field nvarchar(400),message nvarchar(2000));\nIF ISJSON(@input)<>1\n INSERT @findings(code,field,message) VALUES(N''CANDIDATE_DOCUMENT_REQUIRED'',NULL,N''the filed document must be a JSON capability-candidate-bundle.v1'');\nELSE BEGIN\n DECLARE @candidate nvarchar(400)=NULLIF(JSON_VALUE(@input,''$.candidateId''),N'''');\n IF JSON_VALUE(@input,''$.contractId'')<>N''capability-candidate-bundle.v1''\n  INSERT @findings(code,field,message) VALUES(N''CANDIDATE_CONTRACT_REQUIRED'',N''contractId'',N''the filed document must declare contractId capability-candidate-bundle.v1'');\n IF @candidate IS NULL\n  INSERT @findings(code,field,message) VALUES(N''CANDIDATE_ID_REQUIRED'',N''candidateId'',N''a candidate must declare its candidateId'');\n IF JSON_VALUE(@input,''$.sourceDigest'') IS NULL\n  INSERT @findings(code,field,message) VALUES(N''SOURCE_DIGEST_REQUIRED'',N''sourceDigest'',N''a candidate must name the digest of the source objective it was authored from'');\n IF JSON_VALUE(@input,''$.author.providerId'') IS NULL OR JSON_VALUE(@input,''$.author.modelId'') IS NULL OR JSON_VALUE(@input,''$.author.invocationDigest'') IS NULL\n  INSERT @findings(code,field,message) VALUES(N''AUTHOR_REQUIRED'',N''author'',N''a candidate must declare providerId, modelId and invocationDigest'');\n IF NOT EXISTS(SELECT 1 FROM OPENJSON(@input,''$.altitudes''))\n  INSERT @findings(code,field,message) VALUES(N''ALTITUDES_REQUIRED'',N''altitudes'',N''a candidate must declare at least one altitude sub-document'');\n IF EXISTS(SELECT 1 FROM OPENJSON(@input,''$.altitudes'') WHERE JSON_VALUE(value,''$.contractId'') IS NULL\n  OR JSON_QUERY(value,''$.preflight.input'') IS NULL OR JSON_QUERY(value,''$.preflight.expected'') IS NULL)\n  INSERT @findings(code,field,message) VALUES(N''ALTITUDE_PREFLIGHT_REQUIRED'',N''altitudes'',N''every altitude must declare its contractId and its preflight input and expected'');\n IF JSON_QUERY(@input,''$.altitudes.capability'') IS NULL\n  INSERT @findings(code,field,message) VALUES(N''CAPABILITY_ALTITUDE_REQUIRED'',N''altitudes.capability'',N''the candidate must declare the capability altitude the filing is anchored on'');\n ELSE BEGIN\n  IF JSON_VALUE(@input,''$.altitudes.capability.preflight.capabilityId'') IS NULL\n   INSERT @findings(code,field,message) VALUES(N''CAPABILITY_PREFLIGHT_REQUIRED'',N''altitudes.capability.preflight.capabilityId'',N''the capability altitude must name the selected estate capability its preflight probes'');\n  IF JSON_QUERY(@input,''$.altitudes.capability.preflight.input'') IS NULL OR JSON_QUERY(@input,''$.altitudes.capability.preflight.expected'') IS NULL\n   INSERT @findings(code,field,message) VALUES(N''CAPABILITY_PREFLIGHT_REQUIRED'',N''altitudes.capability.preflight'',N''the capability altitude must declare preflight input and expected'');\n  IF JSON_VALUE(@input,''$.altitudes.capability.preflight.disposition'') IS NULL\n   INSERT @findings(code,field,message) VALUES(N''CAPABILITY_PREFLIGHT_REQUIRED'',N''altitudes.capability.preflight.disposition'',N''the capability altitude must name the expected execution disposition'');\n END\n IF JSON_VALUE(@input,''$.receiptRef.contractId'')<>N''capability-candidate-receipt.v1''\n  INSERT @findings(code,field,message) VALUES(N''RECEIPT_CONTRACT_NOT_DECLARED'',N''receiptRef.contractId'',N''the receiptRef must name the declared contract capability-candidate-receipt.v1'');\n IF JSON_VALUE(@input,''$.receiptRef.namespaceId'')<>N''sidefx:candidates''\n  INSERT @findings(code,field,message) VALUES(N''RECEIPT_NAMESPACE_NOT_DECLARED'',N''receiptRef.namespaceId'',N''the receiptRef must name the sidefx:candidates namespace'');\n IF @candidate IS NOT NULL AND JSON_VALUE(@input,''$.receiptRef.declaredId'')<>@candidate+N''.receipt.v1''\n  INSERT @findings(code,field,message) VALUES(N''RECEIPT_ID_MISMATCH'',N''receiptRef.declaredId'',N''the receiptRef declared id must be <candidateId>.receipt.v1'');\n IF JSON_VALUE(@input,''$.receiptRef.state'')<>N''PENDING''\n  INSERT @findings(code,field,message) VALUES(N''RECEIPT_REF_NOT_PLACEHOLDER'',N''receiptRef.state'',N''filing accepts only the PENDING receiptRef placeholder'');\n DECLARE @digest nvarchar(100)=N''sha256:''+LOWER(CONVERT(varchar(64),HASHBYTES(''SHA2_256'',CONVERT(varbinary(max),CONVERT(varchar(max),@input COLLATE Latin1_General_100_BIN2_UTF8))),2));\n DECLARE @prior nvarchar(max)=(SELECT JSON_QUERY(definition_json,''$.semantics.document'') FROM analysis.v_selected_semantic_definition\n  WHERE estate_model_pk=@estate_model_pk AND object_kind=''AUTHORITY'' AND namespace_id=N''sidefx:candidates'' AND declared_id=@candidate+N''.receipt.v1'');\n IF @prior IS NOT NULL AND JSON_VALUE(@prior,''$.bundleDigest'')<>@digest\n  INSERT @findings(code,field,message) VALUES(N''CANDIDATE_REVISION_NOT_ADMITTED'',N''candidateId'',N''this candidate id already has a receipt for different bundle bytes; a revision requires a new candidate id'');\nEND\nDECLARE @reason nvarchar(max)=ISNULL((SELECT code,field,message FROM @findings ORDER BY ordinal FOR JSON PATH),N''[]'');\nSELECT CASE WHEN (SELECT COUNT(*) FROM @findings)=0 THEN N''ADMITTED'' ELSE N''HELD'' END AS disposition,@reason AS reason;"}],"digestAlgorithm":"sha256 of canonical recursive-key-order JSON excluding authorityDigest","sessionPolicy":{"modelDefinitions":{"statement":"SELECT s.name+''.''+o.name AS object_name,o.type,m.definition FROM sys.objects o JOIN sys.schemas s ON s.schema_id=o.schema_id JOIN sys.sql_modules m ON m.object_id=o.object_id WHERE s.name IN(''sidefx'',''analysis'') AND o.type IN(''V'',''IF'',''TF'',''FN'') ORDER BY s.name COLLATE Latin1_General_100_BIN2,o.name COLLATE Latin1_General_100_BIN2","purpose":"The declared view/function definitions the pinned session digests as viewDefinitionDigest."},"impersonation":{"statement":"EXECUTE AS USER=''sidefx_reader'' WITH NO REVERT; SET LOCK_TIMEOUT 30000;","purpose":"The declared reader identity every read in the pinned session runs as."}},"guardSuspensions":[{"guardSetId":"model-write-guards","guards":[],"description":"The inspected estate has no model/source DML triggers. This explicitly