DECLARE @bytes varbinary(max)=CONVERT(varbinary(max),CONVERT(varchar(max),@body COLLATE Latin1_General_100_BIN2_UTF8));
DECLARE @content binary(32)=HASHBYTES('SHA2_256',@bytes);
IF LOWER(CONVERT(varchar(64),@content,2))<>REPLACE(@new_content,N'sha256:',N'') THROW 51000,N'CANDIDATE_FILING_CONTENT_DIVERGED',1;
IF @selected=@prior_content
BEGIN
 IF NOT EXISTS(SELECT 1 FROM source.content_object WHERE content_digest=@content)
  INSERT source.content_object(content_digest,content_bytes,byte_length) VALUES(@content,@bytes,DATALENGTH(@bytes));
 IF (SELECT content_bytes FROM source.content_object WHERE content_digest=@content)<>@bytes
  THROW 51000,N'CANDIDATE_FILING_CONTENT_DIVERGED',1;
 DECLARE @semantics nvarchar(max)=(SELECT JSON_QUERY(definition_json,'$.semantics') FROM analysis.v_selected_semantic_definition
  WHERE estate_model_pk=@estate AND object_kind='AUTHORITY' AND declared_id=@authority_id);
 SET @semantics=JSON_MODIFY(@semantics,'$.contentDigest',@new_content);
 DECLARE @object bigint,@definition bigint,@digest binary(32);
 EXEC model.put_semantic_definition 'AUTHORITY',N'sidefx:authorities',@authority_id,@semantics,@object OUTPUT,@definition OUTPUT,@digest OUTPUT;
END
-- In-transaction preflight of the exact ground read the kernel boot carries.
DECLARE @ground nvarchar(max)=N'SELECT co.byte_length,LOWER(CONVERT(varchar(64),co.content_digest,2)) AS content_digest,co.content_bytes
FROM analysis.v_selected_semantic_definition d
JOIN source.content_object co ON co.content_digest=CONVERT(binary(32),REPLACE(JSON_VALUE(d.definition_json,''$.semantics.contentDigest''),''sha256:'',''''),2)
WHERE d.estate_model_pk=@estate_model_pk AND d.object_kind=''AUTHORITY'' AND d.declared_id=N''sda-kernel-boot-data-access.v1''';
DECLARE @ground_authority TABLE (byte_length bigint,content_digest varchar(71),content_bytes varbinary(max));
INSERT @ground_authority EXEC sp_executesql @ground,N'@estate_model_pk bigint',@estate;
IF (SELECT COUNT_BIG(*) FROM @ground_authority)<>1 THROW 51000,N'CANDIDATE_FILING_GROUND_NOT_SINGULAR',1;
IF (SELECT content_digest FROM @ground_authority)<>REPLACE(@new_content,N'sha256:',N'') THROW 51000,N'CANDIDATE_FILING_CONTENT_NOT_DECLARED',1;
DECLARE @declared nvarchar(max)=(SELECT CONVERT(nvarchar(max),CONVERT(varchar(max),content_bytes) COLLATE Latin1_General_100_BIN2_UTF8) FROM @ground_authority);
IF JSON_VALUE(@declared,'$.authorityDigest')<>N'sha256:a34639fce305a43c02c4cc5f072a4e3a98c1f1ba90ffb23739d321a9e21a7db3' THROW 51000,N'CANDIDATE_FILING_AUTHORITY_DIGEST_DIVERGED',1;
IF (SELECT COUNT(*) FROM OPENJSON(@declared,'$.changeKinds') WHERE JSON_VALUE(value,'$.changeKind')=N'capability-candidate')<>1
 OR (SELECT COUNT(*) FROM OPENJSON(@declared,'$.changeAdmissions') WHERE JSON_VALUE(value,'$.readId')=N'admit-capability-candidate')<>1
 OR (SELECT COUNT(*) FROM OPENJSON(@declared,'$.changeOperations') WHERE JSON_VALUE(value,'$.changeId')=N'file-capability-candidate')<>1
 OR (SELECT COUNT(*) FROM OPENJSON(@declared,'$.reads') WHERE JSON_VALUE(value,'$.readId')=N'admit-capability-candidate')<>1
 OR (SELECT COUNT(*) FROM OPENJSON(@declared,'$.changeContracts') WHERE [key] IN (N'capability-candidate-bundle.v1',N'capability-candidate-receipt.v1',N'capability-candidate-filed.v1',N'alignment-evaluation.v1'))<>4
 THROW 51000,N'CANDIDATE_FILING_DECLARATION_INCOMPLETE',1;
IF OBJECT_ID(N'model.register_capability_candidate') IS NULL THROW 51000,N'CANDIDATE_FILING_INSTALLER_MISSING',1;
SELECT N'capability_candidate_filing_declared' AS result_set,@authority_id AS authority_id,
 (SELECT content_digest FROM @ground_authority) AS content_digest,
 N'provider-binding,scenario-registration,capability-candidate' AS admitted_kinds,
 CASE WHEN @selected=@new_content THEN N'already_declared' ELSE N'redeclared' END AS disposition;
COMMIT TRANSACTION;
